                    "longflag": "output-image",
                    "index": 1,
                    "channel": "output",
                    "default": {
                        "type": "string"
                    }
                }
            ]
        },
        {
            "label": "Kernel",
            "description": "Kernel size and coordinate system for the median filter.",
